using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: discriminator property renamed from "Discriminator" to "$type".
        // Preserve old name so existing documents remain queryable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change: id format changed from "Blog|1" to just "1".
        // Preserve old compound format so existing documents remain accessible.
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // Breaking change: HasIndex now throws for Cosmos entities.
        // Removed — manage indexing via Azure Portal / Bicep / Terraform instead.
        // Was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

arguments.old_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

arguments.new_str:
using Microsoft.EntityFrameworkCore;
class SyncJob
{
    // Breaking change: Cosmos provider no longer supports sync I/O.
    // ToList() and SaveChanges() must become async equivalents.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

